/// <reference types="vite/client" />

declare module '*.module.css' {
  const classes: Record<string, string>
  export default classes
}

declare module '*.css'

// recentlyUpdated.json is generated by `pnpm generate-recently-updated` (in
// website's `prebuild`) and gitignored, so a fresh checkout's `tsc --noEmit`
// cannot resolve it. Declared rather than generated in CI: the generator reads
// processedHubJson/all.json, which `predev` pulls from S3. `unknown[]` because
// recentlyUpdatedData.ts narrows it.
declare module '*/recentlyUpdated.json' {
  const rows: unknown[]
  export default rows
}

// Written beside public/searchIndex.json by `pnpm generate-search-index`, for
// the same reason and with the same shape as its borrowed names: db -> the
// common names GenArk gives that organism.
declare module '*/ucscAliases.json' {
  const aliases: Record<string, string[]>
  export default aliases
}
